import java.util.Scanner;

public class Main {
    static final long E5 = 100000L;
    static final long E6 = 1000000L;
    static final long E7 = 10000000L;
    static final long E9 = 1000000000L;
    static final long MODULUS = E9 + 7;

    static long modularExponentiation(long base, long exponent, long modulus) {
        long result = 1;
        while (exponent > 0) {
            if ((exponent & 1) == 1) {
                result = (result * base) % modulus;
            }
            base = (base * base) % modulus;
            exponent >>= 1;
        }
        return result;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextLong()) {
            long p = sc.nextLong();
            long k = sc.nextLong();

            if (k == 0) {
                System.out.println(modularExponentiation(p, p - 1, MODULUS));
                continue;
            }
            if (k == 1) {
                System.out.println(modularExponentiation(p, p, MODULUS));
                continue;
            }

            boolean[] visited = new boolean[(int) p];
            long cycleCount = 0;

            for (long i = 1; i < p; ++i) {
                if (visited[(int) i]) continue;
                long j = i;
                long length = 0;
                while (!visited[(int) j]) {
                    visited[(int) j] = true;
                    j = (j * k) % p;
                    length++;
                }
                if (modularExponentiation(k, length, p) == 1) {
                    cycleCount++;
                }
            }
            System.out.println(modularExponentiation(p, cycleCount, MODULUS));
        }
        sc.close();
    }
}
